import { Component, OnInit } from '@angular/core';
import { ITenantSettings } from '../utils/models/app-settings.model';
import { TenantSettingsStore } from '../utils/providers/tenant-settings.service';
import { Router } from '@angular/router';

@Component({
  selector: 'page-maintenance',
  templateUrl: 'maintenance.html',
  styleUrls: ['./maintenance.scss'],
})
export class MaintenancePageComponent implements OnInit {
  public isShowUIBigY: boolean;
  private _tenantSettings: ITenantSettings;
  constructor(
    private tenantSettingsStore: TenantSettingsStore,
    private router: Router
  ) {}
  async ngOnInit() {
    try {
      this._tenantSettings = await this.tenantSettingsStore.getTenantSettings();
      if (this._tenantSettings?.maintenanceMode === false) {
        this.router.navigateByUrl('/');
        return;
      }
    } catch (error) {
      console.warn(error);
    }
    this.isShowUIBigY = (window as any).TenantId === 10008;
  }
}
